package com.example.retropong.audio

import android.media.AudioManager
import android.media.ToneGenerator
import com.example.retropong.game.GameEvent

/** Retro beeps generated by the system, so the app needs no audio files and no permissions. */
class SoundManager {

    private val tone: ToneGenerator? = try {
        ToneGenerator(AudioManager.STREAM_MUSIC, 70)
    } catch (e: RuntimeException) {
        null
    }

    fun play(event: GameEvent) {
        when (event) {
            GameEvent.WALL_HIT -> tone?.startTone(ToneGenerator.TONE_PROP_BEEP, 30)
            GameEvent.PLAYER_HIT, GameEvent.AI_HIT -> tone?.startTone(ToneGenerator.TONE_PROP_BEEP2, 40)
            GameEvent.PLAYER_SCORED -> tone?.startTone(ToneGenerator.TONE_PROP_ACK, 150)
            GameEvent.AI_SCORED -> tone?.startTone(ToneGenerator.TONE_PROP_NACK, 150)
            GameEvent.GAME_OVER -> tone?.startTone(ToneGenerator.TONE_PROP_PROMPT, 300)
        }
    }

    fun release() {
        tone?.release()
    }
}
